const raw = $json.output || $json.text || '';
let parsed = {};
try {
  const jsonMatch = raw.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    parsed = JSON.parse(jsonMatch[0]);
  } else {
    parsed = { reply: raw, intent: 'Warm', need: 'General Inquiry', summary: raw.slice(0, 100) };
  }
} catch (err) {
  parsed = { reply: raw, intent: 'Warm', need: 'General Inquiry', summary: 'Parse fallback' };
}

const trigger = $('WhatsApp Trigger').item.json;
const phone = trigger.messages?.[0]?.from || '';
const originalMsg = trigger.messages?.[0]?.text?.body || '';
const profileName = trigger.contacts?.[0]?.profile?.name || parsed.name || 'Valued Customer';

return {
  json: {
    reply: parsed.reply || 'नमस्कार! तुमचा संदेश मिळाला आहे. आम्ही लवकरच तुमच्याशी संपर्क साधू.',
    name: profileName,
    phone: phone,
    customer_message: originalMsg,
    need: parsed.need || 'N/A',
    intent: parsed.intent || 'Warm',
    summary: parsed.summary || originalMsg,
    timestamp: new Date().toISOString()
  }
};

